<template>
  <div class="homework-page">
    <div class="page-header-row">
      <div><span class="eyebrow">একাডেমিক কার্যক্রম</span><h1>দৈনিক বাড়ির কাজ</h1><p>শিক্ষার্থীদের গৃহকাজ, সময়সীমা ও জমা পর্যবেক্ষণ করুন</p></div>
      <button class="btn btn-primary" type="button" @click="showForm = !showForm"><icon name="plus" /> নতুন গৃহকাজ</button>
    </div>

    <div class="toolbar card"><div class="search-box"><icon name="search" /><input v-model="search" placeholder="গৃহকাজ খুঁজুন..." @keyup.enter="load" /></div><select v-model="status" class="form-control compact" @change="load"><option value="">সব অবস্থা</option><option value="true">সক্রিয়</option><option value="false">নিষ্ক্রিয়</option></select><button class="btn btn-outline btn-sm" type="button" @click="load"><icon name="refresh" /> রিফ্রেশ</button></div>

    <form v-if="showForm" class="create-panel card" @submit.prevent="createHomework"><div class="form-heading"><div><h2>নতুন গৃহকাজ তৈরি</h2><p>প্রয়োজনীয় তথ্য পূরণ করুন</p></div><button type="button" class="close-btn" @click="showForm = false">×</button></div><div v-if="formError" class="alert alert-error">{{ formError }}</div><div class="form-grid"><div class="form-group wide"><label>শিরোনাম *</label><input v-model="form.title_bn" class="form-control" required placeholder="যেমন: বাংলা অনুচ্ছেদ লিখুন" /></div><div class="form-group"><label>জমা দেওয়ার তারিখ</label><input v-model="form.due_date" type="date" class="form-control" /></div><div class="form-group wide"><label>বিস্তারিত নির্দেশনা</label><textarea v-model="form.description_bn" class="form-control" rows="3" placeholder="শিক্ষার্থীদের জন্য নির্দেশনা..."></textarea></div><div class="form-group"><label>সর্বোচ্চ নম্বর</label><input v-model.number="form.max_score" type="number" min="0" class="form-control" /></div></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">{{ saving ? 'সংরক্ষণ হচ্ছে...' : 'গৃহকাজ প্রকাশ করুন' }}</button><button class="btn btn-ghost" type="button" @click="showForm = false">বাতিল</button></div></form>

    <div v-if="loading" class="loading-state"><div class="spinner" /><p>গৃহকাজ লোড হচ্ছে...</p></div><div v-else-if="!items.length" class="empty-card"><div class="empty-icon"><icon name="book" /></div><h3>এখনও কোনো গৃহকাজ নেই</h3><p>নতুন গৃহকাজ তৈরি করে শিক্ষার্থীদের কাজ দেওয়া শুরু করুন</p><button class="btn btn-primary" @click="showForm = true">প্রথম গৃহকাজ তৈরি করুন</button></div><div v-else class="homework-grid"><article v-for="item in items" :key="item.id" class="homework-card"><div class="card-top"><span class="subject-chip">{{ item.subject?.name_bn || 'সাধারণ' }}</span><span class="status" :class="item.is_active ? 'active' : 'inactive'">{{ item.is_active ? 'সক্রিয়' : 'নিষ্ক্রিয়' }}</span></div><h3>{{ item.title_bn || item.title_en }}</h3><p class="description">{{ item.description_bn || 'কোনো নির্দেশনা যোগ করা হয়নি' }}</p><div class="meta-row"><span><icon name="academic" /> {{ item.class?.name_bn || 'সব শ্রেণি' }}</span><span><icon name="calendar" /> {{ formatDate(item.due_date) }}</span></div><div class="card-footer"><span class="teacher"><span class="avatar">{{ initials(item.teacher?.user?.name_bn) }}</span>{{ item.teacher?.user?.name_bn || 'শিক্ষক নির্ধারিত নয়' }}</span><NuxtLink :to="`/homework/${item.id}`" class="view-link">বিস্তারিত <icon name="arrow-right" /></NuxtLink></div></article></div>
  </div>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useApiClient } from '~/utils/api'
const api = useApiClient(); const items = ref<any[]>([]); const loading = ref(true); const saving = ref(false); const showForm = ref(false); const formError = ref(''); const search = ref(''); const status = ref(''); const form = reactive({ title_bn: '', description_bn: '', due_date: '', max_score: 100 })
async function load() { loading.value = true; try { const q = new URLSearchParams(); if (search.value) q.set('search', search.value); if (status.value) q.set('is_active', status.value); const r = await api.get(`/homework-assignments?${q}`); items.value = r.data?.data?.data || r.data?.data || [] } catch (e) { console.error(e) } finally { loading.value = false } }
async function createHomework() { saving.value = true; formError.value = ''; try { await api.post('/homework-assignments', form); form.title_bn = ''; form.description_bn = ''; form.due_date = ''; form.max_score = 100; showForm.value = false; await load() } catch (e: any) { formError.value = e?.response?.data?.message || 'গৃহকাজ তৈরি করা যায়নি' } finally { saving.value = false } }
function formatDate(v: string) { return v ? new Date(v).toLocaleDateString('bn-BD', { day: 'numeric', month: 'short', year: 'numeric' }) : 'তারিখ নেই' }
function initials(v?: string) { return v?.trim()?.charAt(0) || 'শি' }
onMounted(load)
</script>

