hadow:var(--shadow-md); border-color:var(--color-primary-100); }.card-top,.meta-row,.card-footer { display:flex; align-items:center; justify-content:space-between; gap:.5rem; }.subject-chip,.status { padding:.24rem .6rem; border-radius:99px; font:.7rem var(--font-bn); }.subject-chip { color:#6f52a2; background:#f0eafb; }.status.active { color:#19724a; background:#e6f4ec; }.status.inactive { color:#a05c35; background:#fff0e4; }.homework-card h3 { margin:1rem 0 .4rem; color:var(--color-text); font:700 1rem var(--font-bn); }.description { min-height:38px; color:var(--color-text-light); font:.8rem/1.55 var(--font-bn); }.meta-row { padding:.85rem 0; margin-top:auto; border-top:1px solid var(--color-border-light); color:var(--color-text-light); font:.72rem var(--font-bn); }.meta-row span { display:inline-flex; align-items:center; gap:.3rem; }.card-footer { padding-top:.7rem; }.teacher { display:flex; align-items:center; gap:.4rem; max-width:60%; overflow:hidden; color:var(--color-text-light); font:.72rem var(--font-bn); white-space:nowrap; text-overflow:ellipsis; }.avatar { display:grid; place-items:center; width:24px; height:24px; flex:0 0 24px; border-radius:50%; color:#fff; background:var(--color-primary); font:700 .7rem var(--font-bn); }.view-link { display:inline-flex; align-items:center; gap:.3rem; color:var(--color-primary); font:600 .75rem var(--font-bn); }.empty-card { padding:3rem; text-align:center; background:#fff; border:1px dashed var(--color-border); border-radius:18px; }.empty-icon { display:grid; place-items:center; width:54px; height:54px; margin:0 auto 1rem; border-radius:16px; color:var(--color-primary); background:var(--color-primary-50); font-size:1.4rem; }.empty-card h3 { font:700 1rem var(--font-bn); }.empty-card p { margin:.4rem 0 1rem; color:var(--color-text-light); font:.8rem var(--font-bn); }
@media(max-width:1050px){.homework-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}@media(max-width:700px){.page-header-row{align-items:flex-start;flex-direction:column}.toolbar{flex-wrap:wrap}.search-box{min-width:100%}.form-grid{grid-template-columns:1fr}.form-group.wide{grid-column:auto}.homework-grid{grid-template-columns:1fr}}
</style>
